        case "background": return background
        case "border": return border
        case "card": return card
        case "card-foreground": return cardForeground
        case "chart-1": return chart1
        case "chart-2": return chart2
        case "chart-3": return chart3
        case "chart-4": return chart4
        case "chart-5": return chart5
        case "credit": return credit
        case "destructive": return destructive
        case "foreground": return foreground
        case "input": return input
        case "muted": return muted
        case "muted-foreground": return mutedForeground
        case "popover": return popover
        case "popover-foreground": return popoverForeground
        case "primary": return primary
        case "primary-foreground": return primaryForeground
        case "ring": return ring
        case "secondary": return secondary
        case "secondary-foreground": return secondaryForeground
        case "sidebar": return sidebar
        case "sidebar-accent": return sidebarAccent
        case "sidebar-accent-foreground": return sidebarAccentForeground
        case "sidebar-border": return sidebarBorder
        case "sidebar-foreground": return sidebarForeground
        case "sidebar-primary": return sidebarPrimary
        case "sidebar-primary-foreground": return sidebarPrimaryForeground
        case "sidebar-ring": return sidebarRing
        case "warning": return warning
        case "window-chrome": return windowChrome
        default:
            assertionFailure("Unknown design token \(token)")
            return Color.red
        }
    }

    /// The same token as a dynamic `NSColor` (for AppKit views), or nil for an unknown name.
    public static func nsColor(named token: String) -> NSColor? {
        guard let pair = components[token] else { return nil }
        return makeNSColor(pair.light, pair.dark)
    }

    /// The token resolved for a given appearance.
    public static func resolved(_ token: String, dark isDark: Bool) -> IMMRGBA? {
        guard let pair = components[token] else { return nil }
        return isDark ? pair.dark : pair.light
    }

    private static func makeNSColor(_ light: IMMRGBA, _ dark: IMMRGBA) -> NSColor {
        NSColor(name: nil) { appearance in
            let isDark = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
            let c = isDark ? dark : light
            return NSColor(srgbRed: c.r, green: c.g, blue: c.b, alpha: c.a)
        }
    }

    private static func dynamicColor(_ light: IMMRGBA, _ dark: IMMRGBA) -> Color {
        Color(nsColor: makeNSColor(light, dark))
    }
}

/// Corner radii in points (`--radius` 0.45rem at 16 px per rem).
public enum IMMRadius {
    /// `--radius`
    public static let base: CGFloat = 7.2
    public static let sm: CGFloat = 4.32
    public static let md: CGFloat = 5.76
    public static let lg: CGFloat = 7.2
    public static let xl: CGFloat = 10.08
    public static let xl2: CGFloat = 12.96
    public static let xl3: CGFloat = 15.84
    public static let xl4: CGFloat = 18.72
    /// `rounded-full`
    public static let full: CGFloat = 9999
}
